package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;
/** Actual formal daily no-input preparation. The repository fact alone is not no-update eligibility. */
class ReportNoUpdateFirstTest {
 boolean mysql(){return false;}
 ReportDailyPreparationIntegrationTest f;ReportPreparedInputService.Prepared original;JdbcReportNoUpdateFirst facts;JdbcReportNoUpdateFirst.Fact proposed;
 void setup()throws Exception{f=new ReportDailyPreparationIntegrationTest(){@Override boolean mysql(){return ReportNoUpdateFirstTest.this.mysql();}};f.setup();var base=f.f.data.nativeData().fixture().f();base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",f.f.data.nativeData().completed().version().contentId());original=f.prepare();facts=new JdbcReportNoUpdateFirst(base.source);var scope=original.scope();proposed=JdbcReportNoUpdateFirst.fact(original.input().ownerId(),scope.logicalKey(),scope.generation(),scope.day(),original.input().inputHash(),original.input().cutoff(),original.receipt().recordedAt(),original.receipt().recordedAt().plusSeconds(1));}
 JdbcReportNoUpdateFirst.Fact read(){return f.f.rr(()->facts.read(original.input().ownerId()));}
 JdbcReportNoUpdateFirst.Fact save(JdbcReportNoUpdateFirst.Fact value){var base=f.f.data.nativeData().fixture().f();return base.writes.execute(new SharedWriteExecutor.ActionContext(JdbcReportNoUpdateFirst.action(value.rootId()),value.rootId(),value.inputHash()),k->null,a->facts.save(value));}
 @Test void ActualNativeFirstHasExactUtcMicroTimeAndReplayNeverMovesOriginalObservation()throws Exception{setup();assertNull(read());assertEquals(proposed,save(proposed));assertEquals(proposed,read());var later=JdbcReportNoUpdateFirst.fact(proposed.rootId(),proposed.logicalKey(),proposed.generation(),proposed.day(),proposed.inputHash(),proposed.cutoff(),proposed.preparedAt(),proposed.observedAt().plusSeconds(9));assertEquals(proposed,save(later));var old=TimeZone.getDefault();try{for(String zone:List.of("UTC","Asia/Shanghai","Asia/Tokyo","America/New_York")){TimeZone.setDefault(TimeZone.getTimeZone(zone));assertEquals(proposed,read());}}finally{TimeZone.setDefault(old);}assertEquals(2,f.f.data.nativeData().fixture().f().sends);assertEquals(0,new JdbcJobRecords(f.f.data.nativeData().fixture().f().source).byId(original.input().ownerId()).callCount());}
 @Test void ProgramActorNativeHashOrPhysicalTimeCorruptionRejectsTheEntireFirstFact()throws Exception{setup();save(proposed);var jdbc=f.f.data.nativeData().fixture().f().jdbc;String id=JdbcFrozenInputs.stableId("report-no-update-first",JdbcReportNoUpdateFirst.action(proposed.rootId()));jdbc.update("UPDATE jobs SET operator_id='fictional-other-program' WHERE id=?",id);assertThrows(RuntimeException.class,this::read);jdbc.update("UPDATE jobs SET operator_id=? WHERE id=?",JdbcReportNoUpdateFirst.ACTOR,id);jdbc.update("UPDATE jobs SET action_payload_hash=UNHEX(?) WHERE id=?","0".repeat(64),id);assertThrows(RuntimeException.class,this::read);setup();save(proposed);var update=f.f.data.nativeData().fixture().f().jdbc;final String target=JdbcFrozenInputs.stableId("report-no-update-first",JdbcReportNoUpdateFirst.action(proposed.rootId()));update.update("UPDATE jobs SET acted_at=? WHERE id=?",ps->{ps.setTimestamp(1,java.sql.Timestamp.from(proposed.observedAt().plusSeconds(1)),Calendar.getInstance(TimeZone.getTimeZone("UTC")));ps.setString(2,target);});assertThrows(RuntimeException.class,this::read);}
 @Test void NativeFirstCannotBeBackdatedOrRehashedToAnotherScopeAndCapacityIsSqlBounded()throws Exception{setup();assertThrows(RuntimeException.class,()->JdbcReportNoUpdateFirst.fact(proposed.rootId(),proposed.logicalKey(),proposed.generation(),proposed.day(),proposed.inputHash(),proposed.cutoff(),proposed.preparedAt(),proposed.preparedAt().minusNanos(1000)));save(proposed);var body=(ObjectNode)CanonicalJson.parse(proposed.payloadJson());body.put("generation",2);String raw=JdbcFrozenInputs.canonical(body);var jdbc=f.f.data.nativeData().fixture().f().jdbc;String id=JdbcFrozenInputs.stableId("report-no-update-first",JdbcReportNoUpdateFirst.action(proposed.rootId()));jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);assertThrows(RuntimeException.class,this::read);jdbc.update("UPDATE jobs SET action_payload=? WHERE id=?",JdbcFrozenInputs.canonical(tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("fictional_capacity","x".repeat(8193))),id);assertThrows(RuntimeException.class,this::read);}
 @Test void NativeFirstFailureRollsBackAndReadonlyOrColdCallsCannotMintAuthority()throws Exception{setup();var ds=org.mockito.Mockito.mock(javax.sql.DataSource.class);new JdbcReportNoUpdateFirst(ds);org.mockito.Mockito.verifyNoInteractions(ds);assertThrows(RuntimeException.class,()->facts.read(proposed.rootId()));assertThrows(RuntimeException.class,()->facts.save(proposed));var jdbc=f.f.data.nativeData().fixture().f().jdbc;jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_no_update_first_failure CHECK(target_type IS NULL OR target_type<>'report_no_update_first')");assertThrows(RuntimeException.class,()->save(proposed));assertNull(read());assertEquals(original,f.originals.find(f.scope));}
}
